import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// In-process double of the downstream pricing service (unit price in euros).
const prices = { A: 10, B: 60, C: 10.5, D: 33.33 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, json, id string, items echoed, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order, { id: order.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
})

test('POST /orders ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders sums several items', async () => {
  const o = await (await post({ items: [{ sku: 'A', qty: 1 }, { sku: 'C', qty: 2 }] })).json()
  assert.equal(o.total, 31)
})

test('POST /orders total is floored, not rounded', async () => {
  const o = await (await post({ items: [{ sku: 'C', qty: 3 }] })).json() // 31.5
  assert.equal(o.total, 31)
})

test('POST /orders exactly 100 gets no discount', async () => {
  const o = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(o.total, 100)
})

test('POST /orders over 100 gets 10% discount', async () => {
  const o = await (await post({ items: [{ sku: 'B', qty: 2 }] })).json() // 120 -> 108
  assert.equal(o.total, 108)
})

test('POST /orders discount applies before flooring', async () => {
  const o = await (await post({ items: [{ sku: 'D', qty: 4 }] })).json() // 133.32 -> 119.988
  assert.equal(o.total, 119)
})

test('POST /orders unknown sku (no price) gives total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - undefined price -> NaN -> serialised as null, still 201
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders negative qty is accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - no qty validation
  const res = await post({ items: [{ sku: 'A', qty: -1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, -10)
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['empty items', { items: [] }],
  ['items not an array', { items: 'x' }],
  ['invalid JSON', null, '{nope'],
  ['empty body', null, ''],
  ['JSON null', null, 'null'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  })
}

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id unknown id answers 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended - a missing order returns 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('GET /orders/:id ignores query string', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.deepEqual(await (await fetch(`${base}/orders/${created.id}?x=1`)).json(), created)
})

for (const [method, path] of [
  ['GET', '/orders'], ['GET', '/'], ['GET', '/orders/1/extra'], ['GET', '/orders/'],
  ['DELETE', '/orders/1'], ['PUT', '/orders/1'], ['POST', '/orders/1'],
]) {
  test(`${method} ${path} -> 404 no route`, async () => {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  })
}
